    iron_bookspineliningcloth = { name = "Železni podstavna tkanina za hrbte", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni podstavna tkanina za hrbte za knjigoveze." },
    bronze_bookspineliningcloth = { name = "Bronast podstavna tkanina za hrbte", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast podstavna tkanina za hrbte za knjigoveze." },
    silver_bookspineliningcloth = { name = "Srebrn podstavna tkanina za hrbte", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn podstavna tkanina za hrbte za knjigoveze." },
    gilded_bookspineliningcloth = { name = "Pozlačen podstavna tkanina za hrbte", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen podstavna tkanina za hrbte za knjigoveze." },
    jewel_set_bookspineliningcloth = { name = "Draguljast podstavna tkanina za hrbte", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast podstavna tkanina za hrbte za knjigoveze." },
    royal_sovereign_bookspineliningcloth = { name = "Kraljevski suveren podstavna tkanina za hrbte", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren podstavna tkanina za hrbte z biseri za krono." },
}
local BUILDINGS = {
    bookspineliningcloth_workshop = { name = "Bookspineliningcloth delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    bookspineliningcloth_house = { name = "Bookspineliningcloth hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_bookspineliningcloth_atelier = { name = "Mojstrski bookspineliningcloth atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_bookspineliningcloth_palace = { name = "Suverena bookspineliningcloth palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
BookSpineLiningClothMaker.ironStock=10; BookSpineLiningClothMaker.bronzeStock=8; BookSpineLiningClothMaker.woodStock=14; BookSpineLiningClothMaker.leatherStock=14; BookSpineLiningClothMaker.silverStock=8; BookSpineLiningClothMaker.goldStock=6; BookSpineLiningClothMaker.jewelStock=4; BookSpineLiningClothMaker.pearlStock=4
BookSpineLiningClothMaker.productStock = {}; BookSpineLiningClothMaker.buildings = {}; BookSpineLiningClothMaker.maker = nil; BookSpineLiningClothMaker.activeMaking = {}; BookSpineLiningClothMaker.totalProducts = 0; BookSpineLiningClothMaker.dayTimer = 0
function BookSpineLiningClothMaker.init() BookSpineLiningClothMaker.ironStock=10; BookSpineLiningClothMaker.bronzeStock=8; BookSpineLiningClothMaker.woodStock=14; BookSpineLiningClothMaker.leatherStock=14; BookSpineLiningClothMaker.silverStock=8; BookSpineLiningClothMaker.goldStock=6; BookSpineLiningClothMaker.jewelStock=4; BookSpineLiningClothMaker.pearlStock=4; BookSpineLiningClothMaker.productStock={}; BookSpineLiningClothMaker.buildings={}; BookSpineLiningClothMaker.maker=nil; BookSpineLiningClothMaker.activeMaking={}; BookSpineLiningClothMaker.totalProducts=0; BookSpineLiningClothMaker.dayTimer=0; print("[BookSpineLiningClothMaker] Royal Book Spine Lining Cloth Maker System initialized (6 products, 4 buildings)") end
function BookSpineLiningClothMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; BookSpineLiningClothMaker.maker={name=n or ("Tkalnik "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Tkalnik najet: %s (spretnost: %d)",BookSpineLiningClothMaker.maker.name,s),"success") end; return true end
function BookSpineLiningClothMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function BookSpineLiningClothMaker.build(id) local ok,e=BookSpineLiningClothMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(BookSpineLiningClothMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function BookSpineLiningClothMaker.getQualityBonus() local b=0; for _,bd in ipairs(BookSpineLiningClothMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function BookSpineLiningClothMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and BookSpineLiningClothMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and BookSpineLiningClothMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and BookSpineLiningClothMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and BookSpineLiningClothMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and BookSpineLiningClothMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and BookSpineLiningClothMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and BookSpineLiningClothMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and BookSpineLiningClothMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #BookSpineLiningClothMaker.buildings==0 then return false,"Potrebna tkalna delavnica" end; if not BookSpineLiningClothMaker.maker then return false,"Potreben tkalnik" end; return true end
function BookSpineLiningClothMaker.make(pt,qty) qty=qty or 1; local ok,e=BookSpineLiningClothMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then BookSpineLiningClothMaker.ironStock=BookSpineLiningClothMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then BookSpineLiningClothMaker.bronzeStock=BookSpineLiningClothMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then BookSpineLiningClothMaker.woodStock=BookSpineLiningClothMaker.woodStock-d.woodCost*qty end; if d.leatherCost then BookSpineLiningClothMaker.leatherStock=BookSpineLiningClothMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then BookSpineLiningClothMaker.silverStock=BookSpineLiningClothMaker.silverStock-d.silverCost*qty end; if d.goldCost then BookSpineLiningClothMaker.goldStock=BookSpineLiningClothMaker.goldStock-d.goldCost*qty end; if d.jewelCost then BookSpineLiningClothMaker.jewelStock=BookSpineLiningClothMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then BookSpineLiningClothMaker.pearlStock=BookSpineLiningClothMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if BookSpineLiningClothMaker.maker then t=math.max(1,t-math.floor(BookSpineLiningClothMaker.maker.skill/13)) end; table.insert(BookSpineLiningClothMaker.activeMaking,{id="bookspineliningcloth_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function BookSpineLiningClothMaker.completeMaking(m) local q=1.0+(BookSpineLiningClothMaker.getQualityBonus()/100); if BookSpineLiningClothMaker.maker then q=q+(BookSpineLiningClothMaker.maker.skill/140) end; q=math.min(2.5,q); BookSpineLiningClothMaker.productStock[m.productType]=(BookSpineLiningClothMaker.productStock[m.productType] or 0)+m.quantity; BookSpineLiningClothMaker.totalProducts=BookSpineLiningClothMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if BookSpineLiningClothMaker.maker then BookSpineLiningClothMaker.maker.itemsMade=BookSpineLiningClothMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then BookSpineLiningClothMaker.maker.skill=math.min(100,BookSpineLiningClothMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Tkanina izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"bookspineliningcloth.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function BookSpineLiningClothMaker.update(dt) if not _G.state then return end; BookSpineLiningClothMaker.dayTimer=BookSpineLiningClothMaker.dayTimer+dt; if BookSpineLiningClothMaker.dayTimer>=30 then BookSpineLiningClothMaker.dayTimer=0; for i=#BookSpineLiningClothMaker.activeMaking,1,-1 do local m=BookSpineLiningClothMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then BookSpineLiningClothMaker.completeMaking(m); table.remove(BookSpineLiningClothMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(BookSpineLiningClothMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if BookSpineLiningClothMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function BookSpineLiningClothMaker.getStats() return {ironStock=BookSpineLiningClothMaker.ironStock,bronzeStock=BookSpineLiningClothMaker.bronzeStock,woodStock=BookSpineLiningClothMaker.woodStock,leatherStock=BookSpineLiningClothMaker.leatherStock,silverStock=BookSpineLiningClothMaker.silverStock,goldStock=BookSpineLiningClothMaker.goldStock,jewelStock=BookSpineLiningClothMaker.jewelStock,pearlStock=BookSpineLiningClothMaker.pearlStock,productStock=BookSpineLiningClothMaker.productStock,numBuildings=#BookSpineLiningClothMaker.buildings,hasMaker=BookSpineLiningClothMaker.maker~=nil,makerName=BookSpineLiningClothMaker.maker and BookSpineLiningClothMaker.maker.name or "—",makerSkill=BookSpineLiningClothMaker.maker and BookSpineLiningClothMaker.maker.skill or 0,activeMaking=#BookSpineLiningClothMaker.activeMaking,totalProducts=BookSpineLiningClothMaker.totalProducts} end
return BookSpineLiningClothMaker
